THOUGHT: Now I understand the bug. In the `pushValue` method:
1. It clones the current array (`arrayFastClone`)
2. It adds a new value at the beginning (`splice(0, 0, value)`)
3. It **never removes** the last element, so the array grows beyond the width

The fix is simple: after adding the new value at index 0, we should remove the last element (at index `this.width`) to maintain the fixed size. Let me create a test script first to verify the issue, then fix it.

```bash
cat <<'EOF' > test_rolling_array.js
// Simple test to verify the issue with FixedRollingArray

// Simulating the arraySeed function
function arraySeed(val, length) {
    const a = [];
    for (let i = 0; i < length; i++) {
        a.push(val);
    }
    return a;
}

// Simulating the current pushValue method
function pushValueCurrent(samples, value, width) {
    let swap = arraySeed(...arraySeed(value, 1), samples); // clone
    swap.splice(0, 0, value);
    return swap;
}

// The fixed pushValue method
function pushValueFixed(samples, value, width) {
    let swap = [...samples]; // clone
    swap.splice(0, 0, value);
    if (swap.length > width) {
        swap.splice(width, 1); // remove the last element
    }
    return swap;
}

console.log("Testing with width = 3:");
let initial = arraySeed(0, 3);
console.log("Initial:", initial);

let current = initial;
let fixed = initial;

console.log("\n--- Current (buggy) behavior ---");
for (let i = 1; i <= 5; i++) {
    current = pushValueCurrent(current, i, 3);
    console.log(`After adding ${i}:`, current);
}

console.log("\n--- Fixed behavior ---");
for (let i = 1; i <= 5; i++) {
    fixed = pushValueFixed(fixed, i, 3);
    console.log(`After adding ${i}:`, fixed);
}
EOF
